eligible = []
n3 = 0
n5 = 0
for lits in iter_clauses(natoms, B):
    good = True
    for l in lits:
        if not lit_ok[l]:
            good = False
            break
    if not good:
        continue
    cmask = 0
    for l in lits:
        cmask |= lit_mask[l]
    if cmask != full:
        if lits == (0, 3):
            print('DBG clause (0,3) cmask popcount', cmask.bit_count(),
                  'xor full popcount', (cmask ^ full).bit_count(),
                  'lit_mask0', lit_mask[0].bit_count(),
                  'lit_mask3', lit_mask[3].bit_count(), file=sys.stderr)
        continue
    pmask = 0
    for l in lits:
        pmask |= probe_lit[l]
    if pmask == probe_full:
        continue
    n5 += 1
    n3 += 1
    ok = True
    for i, l in enumerate(lits):
        wm = lit_mask[l]
        for j, l2 in enumerate(lits):
            if j != i:
                wm &= lit_neg[l2]
        for sm in src_masks:
            if (wm & sm).bit_count() < W:
                ok = False
                break
        if not ok:
            break
    if ok:
        eligible.append((pmask, lits))

print('n3', n3, 'n5', n5, 'eligible', len(eligible),
      'litok', sum(lit_ok), 'full', full.bit_count(), 'ntrain', n_train,
      'nprobe', n_probe, 'natoms', natoms, 'B', B, 'S', S, 'W', W,
      'srcmasks', [sm.bit_count() for sm in src_masks][:4], file=sys.stderr)
sig_map = {}
